import sys

sys.setrecursionlimit(300000)


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


class TNode:
    def __init__(self, v):
        self.val = v
        self.left = None
        self.right = None


def build_tree(tokens):
    it = iter(tokens)
    first = next(it, -1)
    if first == -1:
        return None
    root = TNode(first)
    q = [root]
    for node in q:
        l = next(it, -1)
        if l != -1:
            node.left = TNode(l)
            q.append(node.left)
        r = next(it, -1)
        if r != -1:
            node.right = TNode(r)
            q.append(node.right)
    return root


def inorder_values(root):
    out = []

    def walk(node):
        if node is None:
            return
        walk(node.left)
        out.append(node.val)
        walk(node.right)

    walk(root)
    return out


def bst_insert(root, x):
    if root is None:
        return TNode(x)
    if x < root.val:
        root.left = bst_insert(root.left, x)
    elif x > root.val:
        root.right = bst_insert(root.right, x)
    return root


