import heapq
import sys


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def process_ops(ops):
    heap = []
    popped = []
    for op, x in ops:
        if op == "push":
            heapq.heappush(heap, x)
        else:
            if heap:
                popped.append(heapq.heappop(heap))
    return popped


def main():
    lines = read_lines()
    ops = []
    for ln in lines[1:]:
        parts = ln.split()
        if parts[0] == "push":
            ops.append(("push", int(parts[1])))
        else:
            ops.append(("pop", 0))
    print(' '.join(map(str, process_ops(ops))))


main()

