    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def kth_largest(nums, k):
    heap = []
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)
    return heap[0]


